ts
import { NextRequest, NextResponse } from "next/server"

const CROSSMINT_API_URL: string = "https://staging.crossmint.com/api/2022-06-09/orders"

type CreateOrderRequestBody = {
  title: string
  price: number
  quantity?: number
  collectionId: string
  bookingDate?: string
  bookingTime?: string
}

type CrossmintPaymentMethod =
  | "base-sepolia"
  | "ethereum-sepolia"
  | "polygon-amoy"
  | "solana-devnet"

type SupportedCurrency = "eth" | "eur" | "usd" | "sol"

type CrossmintCreateOrderPayment = {
  method: CrossmintPaymentMethod
  currency: SupportedCurrency
  payerAddress?: string
  receiptEmail?: string
}

type CrossmintCreateOrderLineItem = {
  collectionLocator?: string
  tokenLocator?: string
  callData?: Record<string, unknown>
}

type CrossmintCreateOrderRequest = {
  payment: CrossmintCreateOrderPayment
  lineItems: CrossmintCreateOrderLineItem[]
  locale?: string
}

type CrossmintCreateOrderResponse = {
  order: {
    orderId: string
    status: string
    payment: {
      method: string
      currency: string
    }
  }
  clientSecret?: string
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0
}

function isPositiveInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value > 0
}

function isNonNegativeNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value) && value >= 0
}

function validateRequestBody(json: unknown): { ok: true; data: CreateOrderRequestBody } | { ok: false; error: string } {
  if (json === null || typeof json !== "object") {
    return { ok: false, error: "Invalid JSON body" }
  }
  const body = json as Partial<CreateOrderRequestBody>

  if (!isNonEmptyString(body.title)) {
    return { ok: false, error: "Field 'title' must be a non-empty string" }
  }

  if (!isNonNegativeNumber(body.price)) {
    return { ok: false, error: "Field 'price' must be a non-negative number" }
  }

  if (!isNonEmptyString(body.collectionId)) {
    return { ok: false, error: "Field 'collectionId' must be a non-empty string" }
  }

  let quantity: number = 1
  if (typeof body.quantity === "undefined") {
    quantity = 1
  } else if (!isPositiveInteger(body.quantity)) {
    return { ok: false, error: "Field 'quantity' must be a positive integer" }
  } else {
    quantity = body.quantity
  }

  if (typeof body.bookingDate !== "undefined" && !isNonEmptyString(body.bookingDate)) {
    return { ok: false, error: "Field 'bookingDate' must be a non-empty string when provided" }
  }

  if (typeof body.bookingTime !== "undefined" && !isNonEmptyString(body.bookingTime)) {
    return { ok: false, error: "Field 'bookingTime' must be a non-empty string when provided" }
  }

  return {
    ok: true,
    data: {
      title: body.title,
      price: body.price,
      quantity,
      collectionId: body.collectionId,
      bookingDate: body.bookingDate,
      bookingTime: body.bookingTime,
    },
  }
}

function buildCrossmintRequestBody(input: CreateOrderRequestBody): CrossmintCreateOrderRequest {
  const totalPrice = input.price * input.quantity
  const callData: Record<string, unknown> = {
    totalPrice: totalPrice.toString(),
    quantity: input.quantity,
  }

  if (input.bookingDate) {
    callData.bookingDate = input.bookingDate
  }

  if (input.bookingTime) {
    callData.bookingTime = input.bookingTime
  }

  callData.title = input.title

  const lineItem: CrossmintCreateOrderLineItem = {
    collectionLocator: `crossmint:${input.collectionId}`,
    callData,
  }

  const requestBody: CrossmintCreateOrderRequest = {
    payment: {
      method: "base-sepolia",
      currency: "eth",
    },
    lineItems: [lineItem],
    locale: "en-US",
  }

  return requestBody
}

export async function POST(request: NextRequest): Promise<NextResponse> {
  const serverApiKey = process.env.CROSSMINT_SERVER_API_KEY
  if (!isNonEmptyString(serverApiKey)) {
    return NextResponse.json(
      { error: "Internal configuration error" },
      { status: 500 }
    )
  }

  let parsedBody: unknown
  try {
    parsedBody = await request.json()
  } catch {
    return NextResponse.json(
      { error: "Invalid JSON payload" },
      { status: 400 }
    )
  }

  const validationResult = validateRequestBody(parsedBody)
  if (!validationResult.ok) {
    return NextResponse.json(
      { error: validationResult.error },
      { status: 400 }
    )
  }

  const orderRequestBody = buildCrossmintRequestBody(validationResult.data)

  let crossmintResponse: Response
  try {
    crossmintResponse = await fetch(CROSSMINT_API_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${serverApiKey}`,
      },
      body: JSON.stringify(orderRequestBody),
    })
  } catch {
    return NextResponse.json(
      { error: "Failed to reach payment provider" },
      { status: 502 }
    )
  }

  if (!crossmintResponse.ok) {
    let errorBody: unknown = null
    try {
      errorBody = await crossmintResponse.json()
    } catch {
      errorBody = null
    }

    return NextResponse.json(
      {
        error: "Payment provider returned an error",
        status: crossmintResponse.status,
        details: errorBody,
      },
      { status: 502 }
    )
  }

  let crossmintJson: CrossmintCreateOrderResponse
  try {
    crossmintJson = (await crossmintResponse.json()) as CrossmintCreateOrderResponse
  } catch {
    return NextResponse.json(
      { error: "Invalid response from payment provider" },
      { status: 502 }
    )
  }

  return NextResponse.json(
    {
      orderId: crossmintJson.order.orderId,
      status: crossmintJson.order.status,
      payment: {
        method: crossmintJson.order.payment.method,
        currency: crossmintJson.order.payment.currency,
      },
      clientSecret: crossmintJson.clientSecret ?? null,
    },
    { status: 201 }
  )
}
